-- Used Clothing Box Data
CREATE TABLE IF NOT EXISTS public.used_clothing_box_stats (district varchar(50), count int, city varchar(50));
CREATE TABLE IF NOT EXISTS public.used_clothing_box_stores (id varchar(50), city varchar(50), district varchar(50), address varchar(300), org varchar(200), lng double precision, lat double precision);
TRUNCATE public.used_clothing_box_stats;
TRUNCATE public.used_clothing_box_stores;
